/// 404 for an event resource. Empty body so existence is not leaked.
fn dav_resource_not_found() -> Response {
    StatusCode::NOT_FOUND.into_response()
}

input.newString:
/// 404 for an event resource. Empty body so existence is not leaked.
fn dav_resource_not_found() -> Response {
    StatusCode::NOT_FOUND.into_response()
}

fn dav_bad_request(message: &str) -> Response {
    (StatusCode::BAD_REQUEST, message).into_response()
}

fn handle_calendar_query(
    accounts: &CaldavAccountService,
    principal_id: &str,
    calendar: &CaldavCalendar,
    cal_query: &CalendarQuery,
) -> Response {
    let repository = CaldavRepository::new(accounts.pool().clone());
    let event_ids = match repository.list_events_in_range(
        calendar.calendar_id,
        cal_query.start_utc,
        cal_query.end_utc,
        MAX_RESULTS,
    ) {
        Ok(ids) => ids,
        Err(_) => return dav_server_error(),
    };
    let events = EventRepository::new(accounts.pool().clone());
    let now = accounts.now();
    let mut responses = Vec::new();
    for event_id in &event_ids {
        let resource = match repository.ensure_resource(calendar.calendar_id, *event_id, now) {
            Ok(resource) => resource,
            Err(_) => return dav_server_error(),
        };
        match events.event(calendar.calendar_id, *event_id) {
            Ok(Some(event)) => {
                if let Some((ical, etag)) = ical_and_etag(&resource, &event) {
                    let href = format!(
                        "/dav/calendars/{principal_id}/{}/{}.ics",
                        calendar.calendar_id, resource.resource_name
                    );
                    responses.push(calendar_query_response_xml(&href, &etag, &ical));
                }
            }
            Ok(None) => {}
            Err(_) => return dav_server_error(),
        }
    }
    let body = if responses.is_empty() {
        String::new()
    } else {
        responses.join("\n")
    };
    let xml = format!(
        r#"<?xml version="1.0" encoding="utf-8" ?>
<D:multistatus xmlns:D="DAV:" xmlns:C="urn:ietf:params:xml:ns:calendarserver/">
{body}
</D:multistatus>"#
    );
    (
        StatusCode::MULTI_STATUS,
        [(header::CONTENT_TYPE, "application/xml; charset=utf-8")],
        xml,
    )
        .into_response()
}

fn calendar_query_response_xml(href: &str, etag: &str, ical: &str) -> String {
    let escaped_ical = xml_escape(ical);
    format!(
        r#"  <D:response>
    <D:href>{href}</D:href>
    <D:propstat>
      <D:prop>
        <D:getetag>{etag}</D:getetag>
        <D:getcontenttype>text/calendar; charset=utf-8</D:getcontenttype>
        <C:calendar-data>{escaped_ical}</C:calendar-data>
      </D:prop>
      <D:status>HTTP/1.1 200 OK</D:status>
    </D:propstat>
  </D:response>"#
    )
}

