    reader.config_mut().trim_text(true);

    let mut buf = Vec::new();
    let mut root_local: Option<String> = None;
    let mut in_filter = false;
    let mut filter_depth: u32 = 0;
    let mut found_time_range = false;
    let mut start_utc: Option<i64> = None;
    let mut end_utc: Option<i64> = None;
    let mut unsupported_in_filter = false;

    loop {
        match reader.read_into(&mut buf) {
            Ok(Event::Start(ref start)) => {
                let name = start.local_name().to_string();
                let local = local_name(&name);
                if root_local.is_none() {
                    if local != "calendar-query" {
                        return Err(QueryError::UnsupportedRoot);
                    }
                    root_local = Some(name);
                    continue;
                }
                if in_filter {
                    filter_depth += 1;
                    if local == "time-range" {
                        found_time_range = true;
                        let attrs: Vec<(String, String)> = start
                            .attributes()
                            .filter_map(|a| a.ok())
                            .map(|a| {
                                (
                                    a.key.to_string(),
                                    a.unescaped_value().map(|v| v.to_string()).unwrap_or_default(),
                                )
                            })
                            .collect();
                        for (key, val) in &attrs {
                            let k = local_name(key);
                            if k == "start" {
                                start_utc = Some(parse_ical_datetime(val)?);
                            } else if k == "end" {
                                end_utc = Some(parse_ical_datetime(val)?);
                            }
                        }
                    } else if local != "filter" {
                        unsupported_in_filter = true;
                    }
                } else if local == "filter" && is_calendar_ns(&name) {
                    in_filter = true;
                    filter_depth = 1;
                }
            }
            Ok(Event::End(ref end)) => {
                let name = end.local_name().to_string();
                let local = local_name(&name);
                if in_filter {
                    filter_depth -= 1;
                    if filter_depth == 0 {
                        in_filter = false;
                    }
                }
            }
            Ok(Event::Eof) => break,
            Ok(_) => {}
            Err(_) => return Err(QueryError::MalformedXml),
        }
