fn local_name(tag: &str) -> &str {
    match tag.rsplit_once(':') {
        Some((_, name)) => name,
        None => tag,
    }
}

fn namespace_of(tag: &str) -> Option<&str> {
    tag.rsplit_once(':').map(|(prefix, _)| prefix)
}

fn is_in_namespace(tag: &str, ns: &str) -> bool {
    match tag.rsplit_once(':') {
        Some((prefix, _)) => {
            prefix == "C" && ns == CALENDAR_NS
                || prefix == "D" && ns == DAV_NS
                || prefix == ns
        }
        None => false,
    }
}

